// Generates src/system.ts: the run-status derivation is written out per task and per move.
import { writeFileSync } from 'node:fs';

const INFLIGHT = ['queued', 'running', 'evicted'];
const MOVES = [
  ['taskStarted', 'queued', 'running'],
  ['taskCompleted', 'running', 'completed'],
  ['taskFailed', 'running', 'failed'],
  ['taskEvicted', 'running', 'evicted'],
  ['taskRequeued', 'evicted', 'queued'],
];
const inflight = (e) => `isIn(${e}, [$.queued, $.running, $.evicted])`;

// The run's status once task i is `to`, and the other two tasks keep a and b.
function derive(to, a, b, ind) {
  const p = ' '.repeat(ind);
  let rest;
  if (to === 'failed') rest = `[set('status', $.failed)]`;
  else {
    const anyInFlight = INFLIGHT.includes(to)
      ? `[set('status', $.running)]`
      : `[when(${inflight(`$.${a}`)} || ${inflight(`$.${b}`)}, [set('status', $.running)], [set('status', $.cancelled)])]`;
    rest = `[when($.${a} === $.failed || $.${b} === $.failed, [set('status', $.failed)], ${anyInFlight})]`;
  }
  return `${p}when($.${a} === $.${to} && $.${b} === $.${to}, [set('status', $.${to})], ${rest})`;
}

function branch(i, from, to, ind) {
  const [a, b] = [0, 1, 2].filter((j) => j !== i).map((j) => `t${j}`);
  const p = ' '.repeat(ind);
  return `[\n${p}  require($.t${i} === $.${from}, 'task-not-${from}'),\n${p}  set('t${i}', $.${to}),\n${derive(to, a, b, ind + 2)},\n${p}]`;
}

const handlers = MOVES.map(([action, from, to]) => `      on('${action}', ($) => [
        require(${inflight('$.status')}, 'run-not-active'),
        when($.task === 0, ${branch(0, from, to, 8)}, [
          when($.task === 1, ${branch(1, from, to, 10)}, ${branch(2, from, to, 10)}),
        ]),
      ], ['task']),`).join('\n');

const src = `// Workflow run status: a run of three tasks, and its status derived from them.
// Generated by gen.mjs.
import { module, enumType, machine, field, t, action, on, require, set, when, isIn, terminal, invariant, implies } from '@cognitive-fab/poly/embed';

export default module('workflow', [
  // 'unstarted' is the state of an instance before Start; a refused start leaves no instance, so no query sees it.
  enumType('Status', ['unstarted', 'queued', 'running', 'evicted', 'completed', 'failed', 'cancelled']),
  machine('Run', {
    state: {
      status: field(t.named('Status'), ($) => $.unstarted),
      t0: field(t.named('Status'), ($) => $.queued),
      t1: field(t.named('Status'), ($) => $.queued),
      t2: field(t.named('Status'), ($) => $.queued),
    },
    items: [
      terminal(($) => isIn($.status, [$.completed, $.failed, $.cancelled])),
      action('start', {}),
${MOVES.map(([a]) => `      action('${a}', { task: t.int.check(0, 2, 'strict') }),`).join('\n')}
      action('cancel', {}),
      on('start', ($) => [
        require($.status === $.unstarted, 'run-exists'),
        set('status', $.queued),
        set('t0', $.queued),
        set('t1', $.queued),
        set('t2', $.queued),
      ]),
${handlers}
      on('cancel', ($) => [
        require(${inflight('$.status')}, 'run-not-active'),
        require(${inflight('$.t0')} || ${inflight('$.t1')} || ${inflight('$.t2')}, 'nothing-in-flight'),
        when(${inflight('$.t0')}, [set('t0', $.cancelled)]),
        when(${inflight('$.t1')}, [set('t1', $.cancelled)]),
        when(${inflight('$.t2')}, [set('t2', $.cancelled)]),
        // No task is in flight afterwards, and three tasks alike can only be three cancelled ones.
        when($.t0 === $.failed || $.t1 === $.failed || $.t2 === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
      ]),
      invariant('tasks-started', ($) => implies($.status !== $.unstarted, $.t0 !== $.unstarted && $.t1 !== $.unstarted && $.t2 !== $.unstarted)),
      invariant('completed-means-all-completed', ($) => implies($.status === $.completed, $.t0 === $.completed && $.t1 === $.completed && $.t2 === $.completed)),
      invariant('failed-shows', ($) => implies($.t0 === $.failed || $.t1 === $.failed || $.t2 === $.failed, $.status === $.failed)),
      invariant('in-flight-shows', ($) => implies(${inflight('$.t0')} || ${inflight('$.t1')} || ${inflight('$.t2')}, $.status === $.unstarted || ${inflight('$.status')})),
    ],
  }),
]);
