import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };
const refused = (r: any) => assert.equal(r.ok, false, JSON.stringify(r));

test('start, unknown runs, duplicates', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  refused(await h.taskStarted('a', 0));
  refused(await h.cancel('a'));
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  refused(await h.start('a'));
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('bad tasks and bad moves', async () => {
  const h = await createHost();
  await h.start('r');
  refused(await h.taskStarted('r', 3));
  refused(await h.taskStarted('r', -1));
  refused(await h.taskStarted('r', 1.5));
  refused(await h.taskCompleted('r', 0));
  refused(await h.taskRequeued('r', 0));
  refused(await h.taskEvicted('r', 0));
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  refused(await h.taskStarted('r', 0));
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'running', task1: 'queued', task2: 'queued' });
});

