test('a failed run with nothing in flight can retry; cancel leaves it failed', async () => {
  const h = await createHost();
  await h.start('r');
  for (const i of [0, 1, 2]) { await h.taskStarted('r', i); await h.taskFailed('r', i); }
  assert.equal((await h.run('r'))!.status, 'failed');
