import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };
const refused = (r: any) => assert.equal(r.ok, false, JSON.stringify(r));
// The view of a run that was never paused, without its `paused` flag.
const view = async (h: any, id: string) => {
  const r = await h.run(id);
  if (r) { assert.equal(r.paused, false); delete r.paused; }
  return r;
};

test('pause and resume', async () => {
  const h = await createHost();
  refused(await h.pause('r'));
  await h.start('r');
  assert.equal((await h.run('r'))!.paused, false);
  refused(await h.resume('r'));
  assert.deepEqual(await h.pause('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued', paused: true });
  refused(await h.pause('r'));
  refused(await h.taskStarted('r', 0));
  assert.deepEqual(await h.resume('r'), ok);
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  await h.taskStarted('r', 1);
  await h.pause('r');
  assert.deepEqual(await h.taskEvicted('r', 0), ok);
  assert.deepEqual(await h.taskRequeued('r', 0), ok);
  assert.deepEqual(await h.taskFailed('r', 1), ok);
  assert.deepEqual(await h.taskRetried('r', 1), ok);
  assert.deepEqual(await h.cancelTask('r', 2), ok);
  assert.deepEqual(await view(h,'r'), { status: 'running', task0: 'queued', task1: 'queued', task2: 'cancelled', paused: true });
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await view(h,'r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: true });
  refused(await h.resume('r'));
});

test('start, unknown runs, duplicates', async () => {
  const h = await createHost();
  assert.equal(await view(h,'a'), null);
  refused(await h.taskStarted('a', 0));
  refused(await h.cancel('a'));
  assert.equal(await view(h,'a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.deepEqual(await view(h,'a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  refused(await h.start('a'));
  assert.deepEqual(await view(h,'a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

